using System;
using System.Collections.Immutable;
using System.Linq;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Records")]
    [TestClass]
    public class RJIT_CR_R_00002 : ControllerTestBase
    {
        [TestMethod]
        public void Please_Do_Not_Mix_Property_And_Constructor_Declarations()
        {
            var mutableProperties = (from syntaxTree in SyntaxTreesToAnalyze
                                     from @record in syntaxTree.Records
                                     where @record.Properties.Any() && @record.Parameters.Any()
                                     select new
                                     {
                                         Error = $@"

Please do not mix property and constructor declarations. If you have required properties, please use modifier 'required' for the properties
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
FullName:  {@record.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Record:

{@record.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:

{@record.ToPropertyDeclaration()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                     }).ToImmutableList();

            Assert.IsTrue(mutableProperties.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_R_00002

Properties must be immutable. Findings: '{mutableProperties.Count}':{Environment.NewLine}{mutableProperties.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
